import React, { useState, useEffect } from 'react';
import { Terminal, Github, Linkedin, Mail, Menu, X } from 'lucide-react';

const Navbar = () => {
  const [scrolled, setScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navLinks = [
    { name: 'Projects', href: '#projects' },
    { name: 'Experience', href: '#experience' },
    { name: 'Skills', href: '#skills' },
    { name: 'Education & Certs', href: '#education' },
    { name: 'Contact', href: '#contact' },
  ];

  return (
    <header className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
      scrolled 
        ? 'bg-dark-950/85 backdrop-blur-md border-b border-dark-700/60 py-3 shadow-lg' 
        : 'bg-transparent py-5'
    }`}>
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 flex items-center justify-between">

        {/* Brand / Logo */}
        <a href="#" className="flex items-center gap-2.5 group">
          <div className="w-9 h-9 rounded-lg bg-dark-850 border border-dark-700 flex items-center justify-center text-cyanNeon-400 group-hover:border-cyanNeon-500/60 transition-colors shadow-sm">
            <Terminal className="w-5 h-5 text-cyanNeon-400" />
          </div>
          <div className="flex flex-col">
            <span className="font-bold text-slate-100 tracking-tight group-hover:text-cyanNeon-400 transition-colors">
              AAYUSH NISAR
            </span>
            <span className="text-[10px] font-mono tracking-wider text-slate-400 uppercase">
              AI & Data Systems
            </span>
          </div>
        </a>

        {/* Desktop Navigation */}
        <nav className="hidden md:flex items-center gap-7">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              className="text-xs uppercase font-mono tracking-wider text-slate-300 hover:text-cyanNeon-400 transition-colors"
            >
              {link.name}
            </a>
          ))}
        </nav>

        {/* External Social Links & Contact CTA */}
        <div className="hidden sm:flex items-center gap-3">
          <a
            href="https://github.com/7Aayush11"
            target="_blank"
            rel="noopener noreferrer"
            aria-label="GitHub Profile"
            className="p-2 text-slate-400 hover:text-white hover:bg-dark-800 rounded-lg transition-colors border border-transparent hover:border-dark-700"
          >
            <Github className="w-4 h-4" />
          </a>
          <a
            href="https://linkedin.com/in/aayush-nisar"
            target="_blank"
            rel="noopener noreferrer"
            aria-label="LinkedIn Profile"
            className="p-2 text-slate-400 hover:text-cyanNeon-400 hover:bg-dark-800 rounded-lg transition-colors border border-transparent hover:border-dark-700"
          >
            <Linkedin className="w-4 h-4" />
          </a>
          <a
            href="mailto:nisarayush1172004@gmail.com"
            className="ml-2 inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-mono text-cyanNeon-400 border border-cyanNeon-500/40 bg-cyanNeon-500/5 hover:bg-cyanNeon-500/15 rounded-md transition-all shadow-sm"
          >
            <Mail className="w-3.5 h-3.5" />
            <span>Connect</span>
          </a>
        </div>

        {/* Mobile menu hamburger */}
        <button
          onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          aria-label="Toggle menu"
          className="md:hidden p-2 text-slate-400 hover:text-white focus:outline-none"
        >
          {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
        </button>
      </div>

      {/* Mobile navigation overlay */}
      {mobileMenuOpen && (
        <div className="md:hidden bg-dark-900 border-b border-dark-700 px-5 pt-3 pb-6 space-y-3">
          {navLinks.map((link) => (
            <a
              key={link.name}
              href={link.href}
              onClick={() => setMobileMenuOpen(false)}
              className="block py-2 text-sm font-mono text-slate-300 hover:text-cyanNeon-400 border-b border-dark-800"
            >
              {link.name}
            </a>
          ))}
          <div className="flex items-center gap-4 pt-3">
            <a
              href="https://github.com/7Aayush11"
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center gap-2 text-sm text-slate-300 hover:text-cyanNeon-400"
            >
              <Github className="w-4 h-4" /> GitHub
            </a>
            <a
              href="https://linkedin.com/in/aayush-nisar"
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center gap-2 text-sm text-slate-300 hover:text-cyanNeon-400"
            >
              <Linkedin className="w-4 h-4" /> LinkedIn
            </a>
          </div>
        </div>
      )}
    </header>
  );
};

export default Navbar;

import React from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import Experience from './components/Experience';
import Projects from './components/Projects';
import Skills from './components/Skills';
import EducationCertifications from './components/EducationCertifications';
import ContactSection from './components/ContactSection';
import Footer from './components/Footer';

function App() {
  return (
    <div className="min-h-screen bg-dark-950 text-slate-200 relative selection:bg-cyan-500/20 selection:text-cyan-300 font-sans">
      {/* Background Ambient Glows */}
      <div className="fixed top-0 left-1/2 -translate-x-1/2 w-full max-w-7xl h-[550px] bg-gradient-to-b from-cyanNeon-500/10 via-emeraldGlow-500/5 to-transparent blur-3xl pointer-events-none -z-10" />
      <div className="fixed bottom-0 right-0 w-96 h-96 bg-cyanNeon-600/5 blur-[120px] pointer-events-none -z-10" />

      {/* Main Navigation */}
      <Navbar />

      <main>
        {/* Hero Section */}
        <Hero />

        {/* Core Projects (High impact AI/LLM applications) */}
        <Projects />

        {/* Professional Experience */}
        <Experience />

        {/* Technical Skills & Capabilities */}
        <Skills />

        {/* Education & Certifications */}
        <EducationCertifications />

        {/* Contact & Inquiries */}
        <ContactSection />
      </main>

      {/* Footer */}
      <Footer />
    </div>
  );
}

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App.jsx';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  body {
    background-color: #07090e;
    color: #e2e8f0;
    overflow-x: hidden;
  }
}

/* Custom subtle scrollbar */
::-webkit-scrollbar {
  width: 8px;
}
::-webkit-scrollbar-track {
  background: #0c1017;
}
::-webkit-scrollbar-thumb {
  background: #1e293b;
  border-radius: 4px;
}
::-webkit-scrollbar-thumb:hover {
  background: #334155;
}

.tech-badge {
  @apply px-2.5 py-1 text-xs font-mono rounded-md bg-dark-800 text-cyan-300 border border-dark-700/60 hover:border-cyanNeon-500/40 transition-colors;
}

.glass-card {
  @apply bg-dark-900/70 backdrop-blur-md border border-dark-700/60 rounded-xl shadow-xl hover:border-cyanNeon-500/30 transition-all duration-300;
}

/** @type {import('tailwindcss').Config} */
export default {
  content: [
    "./index.html",
    "./src/**/*.{js,ts,jsx,tsx}",
  ],
  theme: {
    extend: {
      colors: {
        dark: {
          950: '#07090e',
          900: '#0c1017',
          850: '#111722',
          800: '#161f2e',
          700: '#233045',
          600: '#344563'
        },
        cyanNeon: {
          400: '#22d3ee',
          500: '#06b6d4',
          600: '#0891b2'
        },
        emeraldGlow: {
          400: '#34d399',
          500: '#10b981'
        },
        amberGlow: {
          400: '#fbbf24',
          500: '#f59e0b'
        }
      },
      fontFamily: {
        sans: ['Inter', 'system-ui', '-apple-system', 'sans-serif'],
        mono: ['JetBrains Mono', 'Fira Code', 'monospace']
      },
      backgroundImage: {
        'grid-pattern': "radial-gradient(rgba(34, 211, 238, 0.08) 1px, transparent 1px)",
        'radial-gradient-hero': "radial-gradient(circle at 50% 20%, rgba(6, 182, 212, 0.15), transparent 70%)"
      }
    },
  },
  plugins: [],
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

// https://vitejs.dev/config/
export default defineConfig({
  plugins: [react()],
  server: {
    port: 3000
  }
});

import React from 'react';
import { motion } from 'framer-motion';
import { GraduationCap, Award, MapPin, Calendar, CheckCircle2 } from 'lucide-react';

const EducationCertifications = () => {
  const education = {
    institution: "Dwarkadas J. Sanghvi College of Engineering",
    period: "Nov 2022 – Jun 2026",
    degree: "B.Tech in Artificial Intelligence and Data Science",
    grade: "CGPA: 7.8 / 10.0",
    location: "Mumbai, India"
  };

  const certifications = [
    {
      title: "OCI 2025 Certified Data Science Professional",
      date: "Oct 2025",
      issuer: "Oracle Cloud Infrastructure"
    },
    {
      title: "Data Analysis Certification",
      date: "Aug 2024",
      issuer: "Professional Data Analytics Track"
    },
    {
      title: "Google AI Essentials",
      date: "Jul 2024",
      issuer: "Google"
    }
  ];

  return (
    <section id="education" className="py-20 relative bg-dark-900/30 border-t border-dark-800/60">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

          {/* Education Column */}
          <div className="lg:col-span-6 space-y-6">
            <div>
              <div className="flex items-center gap-2 text-cyanNeon-400 font-mono text-xs uppercase tracking-wider mb-2">
                <GraduationCap className="w-4 h-4" />
                <span>Academic Foundation</span>
              </div>
              <h2 className="text-2xl sm:text-3xl font-extrabold text-white tracking-tight">
                Education
              </h2>
            </div>

            <motion.div
              initial={{ opacity: 0, y: 15 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              className="glass-card p-6 sm:p-7 space-y-4"
            >
              <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-1">
                <span className="text-xs font-mono px-2.5 py-1 rounded bg-cyanNeon-500/10 text-cyanNeon-400 border border-cyanNeon-500/20 w-fit">
                  {education.grade}
                </span>
                <span className="flex items-center gap-1.5 text-xs font-mono text-slate-400">
                  <Calendar className="w-3.5 h-3.5 text-slate-500" />
                  {education.period}
                </span>
              </div>

              <div>
                <h3 className="text-xl font-bold text-white">
                  {education.degree}
                </h3>
                <p className="text-cyanNeon-400 font-medium text-sm mt-1">
                  {education.institution}
                </p>
              </div>

              <div className="flex items-center gap-1.5 text-xs font-mono text-slate-400 pt-3 border-t border-dark-800">
                <MapPin className="w-3.5 h-3.5 text-cyanNeon-400" />
                <span>{education.location}</span>
              </div>
            </motion.div>
          </div>

          {/* Certifications Column */}
          <div className="lg:col-span-6 space-y-6">
            <div>
              <div className="flex items-center gap-2 text-emeraldGlow-400 font-mono text-xs uppercase tracking-wider mb-2">
                <Award className="w-4 h-4" />
                <span>Credentials</span>
              </div>
              <h2 className="text-2xl sm:text-3xl font-extrabold text-white tracking-tight">
                Certifications
              </h2>
            </div>

            <div className="space-y-3.5">
              {certifications.map((cert, idx) => (
                <motion.div
                  key={cert.title}
                  initial={{ opacity: 0, x: 15 }}
                  whileInView={{ opacity: 1, x: 0 }}
                  viewport={{ once: true }}
                  transition={{ delay: idx * 0.1 }}
                  className="glass-card p-4 sm:p-5 flex items-start gap-3.5"
                >
                  <div className="p-2 rounded-lg bg-emeraldGlow-500/10 border border-emeraldGlow-500/20 text-emeraldGlow-400 flex-shrink-0 mt-0.5">
                    <CheckCircle2 className="w-4 h-4" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-1">
                      <h4 className="text-sm sm:text-base font-semibold text-white leading-tight">
                        {cert.title}
                      </h4>
                      <span className="text-xs font-mono text-slate-400 whitespace-nowrap">
                        {cert.date}
                      </span>
                    </div>
                    <p className="text-xs text-slate-400 mt-1">
                      {cert.issuer}
                    </p>
                  </div>
                </motion.div>
              ))}
            </div>

          </div>

        </div>

      </div>
    </section>
  );
};

export default EducationCertifications;

