                  </div>

                  <div className="flex flex-wrap gap-2">
                    {cat.skills.map((skill) => (
                      <span
                        key={skill}
                        className="px-2.5 py-1 text-xs font-mono rounded bg-dark-850/90 text-slate-200 border border-dark-700/80 hover:border-cyanNeon-500/50 hover:text-cyanNeon-400 transition-colors"
                      >
                        {skill}
                      </span>
                    ))}
                  </div>
                </div>

                <div className="mt-5 pt-3 border-t border-dark-800 text-[11px] font-mono text-slate-500">
                  {cat.skills.length} core competencies
                </div>
              </motion.div>
            );
          })}
