import React from 'react';
import { motion } from 'framer-motion';
import { Briefcase, Calendar, Building2, CheckCircle } from 'lucide-react';

const experiences = [
  {
    role: "AI Model Finetuning Intern",
    company: "SortMyPrep",
    period: "Apr 2026 – Jul 2026",
    deliverables: [
      "Curated, validated, and structured 80+ academic datasets for AI-powered learning systems, performing OCR validation, data cleaning, and document quality assurance to improve downstream LLM fine-tuning data reliability.",
      "Normalized complex mathematical and technical content across 80+ papers, directly improving input data quality and annotation consistency for educational AI model pipelines.",
      "Collaborated with the AI operations team on preprocessing pipeline standards, contributing structured datasets to active model fine-tuning workflows."
    ],
    skills: ["LLM Fine-Tuning", "OCR Validation", "Dataset Quality Assurance", "Mathematical Content Normalization", "AI Preprocessing"]
  },
  {
    role: "Data Visualization Intern",
    company: "Infosys Springboard",
    period: "Nov 2024 – Jan 2025",
    deliverables: [
      "Performed EDA and statistical analysis on urban GDP and socio-economic datasets, identifying regional growth trends to support data-driven decisions.",
      "Built dynamic Power BI dashboards with custom DAX measures and deployed an end-to-end Streamlit interface, presenting insights to a panel of senior stakeholders."
    ],
    skills: ["EDA", "Statistical Analysis", "Power BI", "DAX Measures", "Streamlit", "Socio-Economic Modeling"]
  }
];

const Experience = () => {
  return (
    <section id="experience" className="py-20 relative bg-dark-900/40 border-y border-dark-800/60">
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">

        {/* Section Header */}
        <div className="mb-14">
          <div className="flex items-center gap-2 text-cyanNeon-400 font-mono text-xs uppercase tracking-wider mb-2">
            <Briefcase className="w-4 h-4" />
            <span>Industry Experience</span>
          </div>
          <h2 className="text-3xl sm:text-4xl font-extrabold text-white tracking-tight">
            Work Experience & Internships
          </h2>
          <p className="text-slate-400 text-sm sm:text-base mt-2 max-w-2xl">
            Hands-on technical contributions in LLM fine-tuning data pipelines and enterprise analytics.
          </p>
        </div>

        {/* Timeline / Experience Cards */}
        <div className="relative border-l-2 border-dark-700/80 pl-6 sm:pl-8 ml-2 sm:ml-4 space-y-12">
          {experiences.map((exp, index) => (
            <motion.div
              key={exp.company + exp.period}
              initial={{ opacity: 0, x: -20 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: index * 0.15 }}
              className="relative"
            >
              {/* Timeline dot */}
              <div className="absolute -left-[31px] sm:-left-[39px] top-1.5 w-4 h-4 rounded-full bg-dark-950 border-2 border-cyanNeon-400 shadow-sm shadow-cyanNeon-500/50" />

              <div className="glass-card p-6 sm:p-7 relative">
                {/* Header info */}
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 pb-4 border-b border-dark-800">
                  <div>
                    <h3 className="text-xl font-bold text-white tracking-tight">
                      {exp.role}
                    </h3>
                    <div className="flex items-center gap-2 text-cyanNeon-400 font-medium text-sm mt-0.5">
                      <Building2 className="w-4 h-4" />
                      <span>{exp.company}</span>
                    </div>
                  </div>
                  <div className="inline-flex items-center gap-1.5 text-xs font-mono text-slate-400 px-3 py-1 rounded bg-dark-800/80 border border-dark-700 w-fit">
                    <Calendar className="w-3.5 h-3.5 text-cyanNeon-400" />
                    <span>{exp.period}</span>
                  </div>
                </div>

                {/* Key Achievements & Work */}
                <div className="mt-4 space-y-3">
                  {exp.deliverables.map((item, i) => (
                    <div key={i} className="flex items-start gap-2.5 text-sm text-slate-300 leading-relaxed">
                      <CheckCircle className="w-4 h-4 text-emeraldGlow-400 flex-shrink-0 mt-0.5" />
                      <span>{item}</span>
                    </div>
                  ))}
                </div>

                {/* Skills used */}
                <div className="mt-5 pt-3 border-t border-dark-800/80 flex flex-wrap gap-2">
                  {exp.skills.map((skill) => (
                    <span key={skill} className="px-2 py-0.5 text-xs font-mono rounded bg-dark-800/60 text-slate-300 border border-dark-700/60">
                      {skill}
                    </span>
                  ))}
                </div>

              </div>
            </motion.div>
          ))}
        </div>

      </div>
    </section>
  );
};

export default Experience;

import React from 'react';
import { motion } from 'framer-motion';
import { Code2, Zap, Shield, Sparkles, Layers, Cpu, CheckCircle2 } from 'lucide-react';

