    imgSlot: "proj-persona-forge",
    imgLabel: "PersonaForge architecture and live preview interface screenshot",
    placeholderSrc: "https://placehold.co/800x480/0d131f/22d3ee?text=PersonaForge\nResume-to-Portfolio+LLM+Pipeline",
    highlights: [
      "Accepts resume as PDF or image, extracting raw text with PyMuPDF & Gemini Vision API",
      "Structured LangChain prompt pipeline converts text into verified JSON schema",
      "Second LLM stage transforms structured JSON into complete styled single-page HTML portfolio",
      "FastAPI backend with input validation, try/except error handling, and distance relevance checks",
      "React frontend with live iframe srcDoc rendering, chat-based editing, and one-click Blob API download in <30s"
